{
  "families": [
    {
      "family": "unrolled_k",
      "ranges": [
        {"param": "data_width", "low": 14, "high": 18, "choices": null},
        {"param": "n_iter", "low": 12, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 3, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "k", "low": 4, "high": 8, "choices": null}
      ],
      "budget_share": 0.8,
      "why": "Only plausible multi-cycle route to the batch constraint. A tick of 32 requests must finish in 0.5 us, so 32*(ceil(N/k)+3)/Fmax <= 0.5 us. Accuracy (max_abs_err <= 2^-12) forces N>=13 (residual angle ~2^-(N-1)) and W>=14 (output LSB 2^-(W-2)=2^-12 at W=14), so c=ceil(N/k)+3 is at best 5 (N=14,k=8), needing Fmax>=320 MHz; smaller k needs even higher Fmax. k is therefore the speed knob and also the area knob (k chained micro-rotations), which is exactly the trade-off to map. W/N/guards are kept just above the accuracy floor (14..18, 12..20, 0..3) because area is the objective and larger values only buy accuracy_bits beyond 12."
    },
    {
      "family": "iterative",
      "ranges": [
        {"param": "data_width", "low": 14, "high": 18, "choices": null},
        {"param": "n_iter", "low": 12, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 3, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.2,
      "why": "Small share to document the boundary rather than to find a winner. iterative needs c=N+3 cycles/result, so the batch constraint becomes 32*(N+3)/Fmax <= 0.5 us, i.e. Fmax >= 64*(N+3) MHz. With the accuracy floor N>=13 that is Fmax >= 1024 MHz, which is not credible in sky130_fd_sc_hd; even N=4 would need 448 MHz. I keep the accuracy-feasible range (W 14..18, N 12..20) so code can confirm no iterative point satisfies both max_abs_err<=2^-12 and sys_p99_batch_us<=0.5, and so any surprising fast corner is not missed."
    }
  ],
  "rationale": "The binding constraint is the system burst: 32 simultaneous requests per 1 us tick, all back within 0.5 us (sys_p99_batch_us <= 0.5). For a multi-cycle unit this is 32*c/Fmax <= 0.5 us where c is cycles/result, so c/Fmax <= 15.6 ns. Accuracy (max_abs_err <= 2^-12, i.e. accuracy_bits >= 12) pins N>=13 and W>=14, which sets c>=N+3=16 for iterative (needs >1 GHz, implausible) and c=ceil(N/k)+3>=5 for unrolled_k at k=8 (needs ~320 MHz, the only credible corner). I therefore put 80% of the budget on unrolled_k with k spanning 4..8 (the speed/area trade-off) and W/N/guards just above the accuracy floor (area is the objective), and 20% on iterative to confirm/deny its feasibility. Both objectives (min area_um2, max accuracy_bits) are covered: the front should run from the smallest W/N/guards/k that still clears 2^-12 up to higher-accuracy, higher-area points. I will re-aim ranges in later rounds from the returned numbers (e.g. widen k or N if the feasible corner sits at a range edge, or drop iterative if it returns nothing feasible)."
}

{

  "decision": "add_family",

  "rationale": "The binding constraints are throughput_msps >= 32 and sys_p99_batch_us <= 0.5, and neither can be reached by the two families tried. iterative and unrolled_k emit one result every several cycles, so their throughput is capped far below 32 MSPS (best seen 8.73 and 5.84 MSPS), and the 32-request burst needs ~64 MSPS of burst rate to clear in 0.5 us — 100% of evaluations violate both, with sys_p99_batch_us best 3.66 us (7x over). Accuracy is not the blocker: iterative already reached 14.37 bits (2^-14.37), well past the 2^-12 requirement, so the fix is architectural, not precision. Only pipelined / pipelined_m emit 1 result/cycle, making throughput = Fmax (easily > 32 MHz) and letting a 32-deep burst drain in ~32 cycles + latency. These families have not been evaluated at all, so the current front is not evidence of infeasibility.",

  "next_plan": {
    "families": [
      {
        "family": "pipelined",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 20, "choices": null},
          {"param": "n_iter", "low": 12, "high": 20, "choices": null},
          {"param": "angle_guard", "low": -1, "high": 3, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["round"]}
        ]
      ,
      "budget_share": 0.6
      ,
      "why": "1 result/cycle => throughput = Fmax; one micro-rotation per stage keeps Fmax high, so both the 32 MSPS rate and the 32-request/0.5us burst are reachable. W>=14/N>=12 keeps accuracy past 2^-12."
      },
      {
        "family": "pipelined_m",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 20, "choices": null},
          {"param": "n_iter", "low": 12, "high": 20, "choices": null},
          {"param": "angle_guard", "low": -1, "high": 3, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["round"]},
          {"param": "m", "low": 2, "high": 8, "choices": null}
        ]
      ,
      "budget_share": 0.4
      ,
      "why": "Same 1 result/cycle throughput but latency ceil(N/m)+2 shrinks with m, which directly helps the p99 batch bound; fewer pipeline registers may also cut area (the min-area objective). Trade-off vs Fmax is exactly what the search should map."
      }
    ],
    "rationale": "Spend the remaining ~40 evals on the only families that can satisfy the throughput/burst constraints, keeping W/N ranges that already proved accurate enough. If pipelined/pipelined_m also fail the L1 batch bound, that is the point to declare infeasible."
  }
}
